// ── Report tab ─────────────────────────────────────────────────────────────────
// People who joined our events but aren't community members — pick and add them.
// people: [{ username, events[], articles?, edits?, formOnly? }]
function NotMembersPanel({ people, members, nameFor, canEdit, profile, showToast, title, note, wiki = DEFAULT_WIKI, addMembers, earlier = new Set() }) {
  const [picked, setPicked] = useState({});
  const [busy, setBusy] = useState(false);
  const existing = useMemo(() => new Set(members.map(m => userKey(m.wikimediaUsername)).filter(Boolean)), [members]);
  const list = (people || []).filter(p => !existing.has(userKey(p.username)));   // capitals ignored
  const hasCounts = list.some(p => p.articles !== undefined);
  const chosen = list.filter(p => picked[p.username] ?? true);
  const returningCount = list.filter(p => earlier.has(p.username)).length;
  if (list.length === 0) return null;

  const add = async () => {
    if (chosen.length === 0) return;
    setBusy(true);
    try {
      await addMembers(chosen.map(p => ({ name: nameFor(p.username), wikimediaUsername: p.username, isActive: true, source: "events" })));
      await addAudit(profile, AUDIT_ACTIONS.IMPORT, "contributors", {
        details: `Added ${chosen.length} event participant${chosen.length === 1 ? "" : "s"} to community members: ${chosen.map(p => p.username).join(", ")}`,
      });
      setPicked({});
      showToast(`Added ${chosen.length} to community members.`);
    } catch (e) {
      alert(`Could not add members: ${e.message}`);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="panel" style={{ border: "1px solid #f0d5b0", background: "#fffaf0", marginBottom: 16 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
        <div className="panel-title" style={{ color: "#b45309", margin: 0 }}>{title} ({list.length})</div>
        {canEdit && <button className="btn btn-primary btn-sm" onClick={add} disabled={busy || chosen.length === 0}>{busy ? "Adding…" : `Add ${chosen.length} to members`}</button>}
      </div>
      <div style={{ fontSize: 12, color: "#666", margin: "6px 0 10px" }}>
        {note}
        {returningCount > 0 && <> <strong style={{ color: "#2563eb" }}>{returningCount} {returningCount === 1 ? "was a member" : "were members"} in an earlier grant</strong> — adding them marks them as <strong>Returning</strong> (retention); the others are new members.</>}
      </div>
      <div style={{ overflowX: "auto" }}>
        <table>
          <thead><tr>{canEdit && <th></th>}<th>Name</th><th>Username</th>{hasCounts && <th>Different articles</th>}{hasCounts && <th>Edits</th>}<th>Events</th></tr></thead>
          <tbody>
            {list.map(p => (
              <tr key={p.username}>
                {canEdit && <td><input type="checkbox" checked={picked[p.username] ?? true} onChange={e => setPicked(x => ({ ...x, [p.username]: e.target.checked }))} /></td>}
                <td style={{ fontWeight: 500 }}>{nameFor(p.username)}</td>
                <td style={{ fontSize: 12 }}>
                  <a href={contribsLink(wiki, p.username)} target="_blank" rel="noopener noreferrer" style={{ color: "#2563eb" }}>{p.username}</a>
                  {p.formOnly && <span className="badge badge-gray" style={{ marginLeft: 6, fontSize: 10 }}>form only</span>}
                  {earlier.has(p.username)
                    ? <span className="badge badge-blue" style={{ marginLeft: 6, fontSize: 10 }} title="Member in an earlier grant — counts as retention when added">Returning</span>
                    : <span className="badge badge-green" style={{ marginLeft: 6, fontSize: 10 }}>New</span>}
                </td>
                {hasCounts && <td style={{ fontWeight: 600 }}>{p.articles}</td>}
                {hasCounts && <td style={{ fontSize: 12 }}>{p.edits}</td>}
                <td style={{ fontSize: 12, color: "#666" }}>{p.events.join(", ")}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// Events for the month with usernames from their linked registration forms.
async function withFormUsernames(events) {
  if (!events.some(ev => (ev.formIds || []).length)) return events;
  const regs = await getAllRegistrations();
  return events.map(ev => {
    const ids = new Set(ev.formIds || []);
    return ids.size ? { ...ev, formUsernames: formJoiners(regs.filter(r => ids.has(r.formId))) } : ev;
  });
}

function Report({ members, community = [], reports, allReports = [], events, scope, profile, canEdit, showToast, org, nameFor, addMembers, monthRange, earlier }) {
  // Months are limited to the selected grant's dates.
  const maxMonth = monthRange && monthRange.end < currentMonth() ? monthRange.end : currentMonth();
  const minMonth = monthRange ? monthRange.start : "";
  const clampMonth = (m) => (minMonth && m < minMonth ? minMonth : m > maxMonth ? maxMonth : m);
  const [month,     setMonth]     = useState(() => clampMonth(lastFullMonth()));
  const [wiki,      setWikiRaw]   = useState(DEFAULT_WIKI);
  const [threshold, setThreshold] = useState(DEFAULT_THRESHOLD);
  // Each project has its own active threshold.
  const setWiki = (w) => { setWikiRaw(w); setThreshold(thresholdFor(w)); };
  const unit = wikiInfo(wiki).unit;
  const [allBusy,   setAllBusy]   = useState("");     // project being fetched by "Fetch all projects"
  const [fresh,     setFresh]     = useState(null);   // { wiki, month, members, stats }
  const [progress,  setProgress]  = useState(null);   // { done, total }
  const [error,     setError]     = useState("");
  const [saving,    setSaving]    = useState(false);

  const eligible = members.filter(m => m.isActive !== false && (m.wikimediaUsername || "").trim());
  const memberNames = useMemo(() => new Map(community.map(m => [normalizeUsername(m.wikimediaUsername), m.name || ""])), [community]);
  const saved = reports.find(r => r.id === reportId(wiki, month, scope));
  const freshMatches = fresh && fresh.wiki === wiki && fresh.month === month && fresh.scope === scope;
  const eventsOnly = scope === "events";
  const scopeName = eventsOnly ? `${wikiLabel(wiki)} — Kilimanjaro events only` : wikiLabel(wiki);
  const monthEvents = eventsOnly ? eventWindowsInMonth(events, month) : [];

  // A fresh fetch wins over the saved copy; its rows follow the threshold live.
  const view = useMemo(() => {
    if (freshMatches) {
      const rows = buildReportRows(fresh.members, fresh.stats, threshold)
        .map(r => (fresh.formOnly?.has(r.username) ? { ...r, formOnly: true } : r));
      return { rows, threshold: Number(threshold) || 0, partial: isPartialMonth(month), isSaved: false, events: fresh.events, notMembers: fresh.notMembers || [] };
    }
    if (saved) {
      // Saved rows keep the name from when they were saved — show the member's current name.
      const rows = (saved.rows || []).map(r => {
        const n = (memberNames.get(normalizeUsername(r.username)) || "").trim();
        return n && n !== r.name ? { ...r, name: n } : r;
      });
      return { rows, threshold: saved.threshold, partial: saved.partial, isSaved: true, saved, events: saved.events || [], notMembers: saved.notMembers || [] };
    }
    return null;
  }, [freshMatches, fresh, saved, threshold, month, memberNames]);

  const activeCount = view ? view.rows.filter(r => r.active).length : 0;
  const editingCount = view ? view.rows.filter(isEditing).length : 0;
  const memberCount = view ? view.rows.length : 0;
  const busy = progress !== null;

  // Count one project for the month → a "fresh" result.
  const fetchFor = async (w, usernames, onProgress) => {
    if (eventsOnly) {
      const inMonth = await withFormUsernames(eventWindowsInMonth(events, month).map(x => x.event));
      const res = await fetchEventMonthStats(usernames, inMonth, month, w, { onProgress });
      return { wiki: w, month, scope, members: eligible, stats: res.stats, formOnly: res.formOnly, notMembers: res.notMembers, events: res.events };
    }
    const stats = await fetchMonthStats(usernames, month, w, { onProgress });
    return { wiki: w, month, scope, members: eligible, stats, events: [] };
  };

  const runFetch = async () => {
    if (eligible.length === 0) { setError("No community members took part in this grant yet (participant list, registration forms or events), or none is marked \"In reports\". Add this grant's events or participants first."); return; }
    if (eventsOnly && events.length === 0) { setError("No Kilimanjaro events added yet. Add them on the Events tab first."); return; }
    setError("");
    setProgress({ done: 0, total: eventsOnly ? 0 : eligible.length });
    const onProgress = (done, total) => setProgress({ done, total });
    const usernames = eligible.map(m => m.wikimediaUsername);
    try {
      setFresh(await fetchFor(wiki, usernames, onProgress));
    } catch (e) {
      setError(`Could not fetch ${eventsOnly ? "Kilimanjaro event contributions" : `from ${wikiLabel(wiki)}`}: ${e.message}`);
    } finally {
      setProgress(null);
    }
  };

  // Save one project's report. One saved report per wiki + month is shared by
  // all grants: keep the rows of other grants' members, replace only this grant's.
  const saveView = async (wiki, view) => {
    const mine = new Set(view.rows.map(r => r.username));
    const original = allReports.find(r => r.id === reportId(wiki, month, scope));
    const rows = [...view.rows, ...((original?.rows || []).filter(r => !mine.has(r.username)))];
    const activeCount = view.rows.filter(r => r.active).length;
    const editingCount = view.rows.filter(isEditing).length;
    const scopeName = eventsOnly ? `${wikiLabel(wiki)} — Kilimanjaro events only` : wikiLabel(wiki);
    await saveContributorReport({
      wiki, month, scope,
      threshold:   view.threshold,
      memberCount: rows.length,
      activeCount: rows.filter(r => r.active).length,
      stillEditingCount: rows.filter(isEditing).length,
      partial:     view.partial,
      rows,
      events:      view.events || [],
      notMembers:  view.notMembers || [],
      generatedBy: profile?.name || "",
      generatedAt: new Date().toISOString(),
    });
    await addAudit(profile, AUDIT_ACTIONS.CREATE, "contributors", {
      targetId: reportId(wiki, month, scope), recordTitle: `${scopeName} ${month}`,
      details: `Saved active contributors report (${scopeLabel(scope)}): ${activeCount} of ${view.rows.length} active (≥${view.threshold} ${wikiInfo(wiki).unit}), ${editingCount} still editing`,
    });
  };

  const save = async () => {
    if (!view || view.isSaved) return;
    setSaving(true);
    try {
      await saveView(wiki, view);
      setFresh(null);
      showToast("Report saved.");
    } catch (e) {
      setError(`Could not save the report: ${e.message}`);
    } finally {
      setSaving(false);
    }
  };

  const best = view ? bestContributors(view.rows) : [];

  // Fetch and save every project for this month (for the "All projects" news).
  const fetchAllProjects = async () => {
    if (eligible.length === 0) { setError("No community members took part in this grant yet, or none is marked \"In reports\"."); return; }
    if (eventsOnly && events.length === 0) { setError("No Kilimanjaro events added yet. Add them on the Events tab first."); return; }
    setError("");
    const usernames = eligible.map(m => m.wikimediaUsername);
    const failed = [];
    try {
      for (const w of WIKIS) {
        setAllBusy(w.label);
        try {
          const f = await fetchFor(w.id, usernames);
          const rows = buildReportRows(f.members, f.stats, w.threshold)
            .map(r => (f.formOnly?.has(r.username) ? { ...r, formOnly: true } : r));
          await saveView(w.id, { rows, threshold: w.threshold, partial: isPartialMonth(month), events: f.events, notMembers: f.notMembers || [] });
        } catch (e) {
          failed.push(`${w.label} (${e.message})`);
        }
      }
      setFresh(null);
      if (failed.length) setError(`Could not fetch: ${failed.join("; ")}`);
      else showToast(`All projects fetched and saved for ${monthLabel(month)}.`);
    } finally {
      setAllBusy("");
    }
  };

  // Every project's report for this month (this grant's members only); the
  // project on screen uses what is shown, even if not saved yet.
  const monthProjects = useMemo(() => {
    const list = WIKIS.map(w => {
      if (w.id === wiki && view) return { wiki: w.id, rows: view.rows };
      const r = reports.find(x => x.id === reportId(w.id, month, scope));
      return r ? { wiki: w.id, rows: r.rows || [] } : null;
    }).filter(Boolean);
    return list;
  }, [reports, wiki, view, month, scope]);

  const printReport = async () => {
    if (!view) return;
    openPrintWindow(monthReportHtml({
      rows: view.rows, month, wikiLabel: scopeName, threshold: view.threshold, partial: view.partial, ...org,
    }));
    await addAudit(profile, AUDIT_ACTIONS.EXPORT, "contributors", {
      recordTitle: `${scopeName} ${month}`, details: "Printed active contributors report",
    });
  };

  const exportCsv = async () => {
    if (!view) return;
    const host = wiki.split(".")[0];
    downloadCsv(`active-contributors-${host}-${month}${eventsOnly ? "-kilimanjaro-events" : ""}.csv`, rowsToCsv(view.rows, { month, wiki, threshold: view.threshold }));
    await addAudit(profile, AUDIT_ACTIONS.EXPORT, "contributors", {
      recordTitle: `${scopeName} ${month}`, details: `Exported active contributors CSV (${memberCount} rows)`,
    });
  };

  return (
    <div>
      <div className="panel" style={{ marginBottom: 20 }}>
        <div className="form-grid">
          <div className="field"><label>Month</label>
            <input type="month" value={month} min={minMonth || undefined} max={maxMonth} onChange={e => e.target.value && setMonth(clampMonth(e.target.value))} />
          </div>
          <div className="field"><label>Wiki</label><WikiSelect value={wiki} onChange={setWiki} /></div>
          <div className="field"><label>Active if different {unit} ≥</label>
            <input type="number" min="1" value={threshold} disabled={!canEdit}
              onChange={e => setThreshold(Math.max(1, Number(e.target.value) || 1))} />
          </div>
        </div>
        <div className="btn-row">
          <button className="btn btn-primary" onClick={runFetch} disabled={busy || !!allBusy}>{busy ? "Fetching…" : `Fetch from ${wikiLabel(wiki)}`}</button>
          {canEdit && <button className="btn" onClick={fetchAllProjects} disabled={busy || !!allBusy} title="Fetch and save every project for this month, for the All projects news">{allBusy ? `Fetching ${allBusy}…` : "Fetch & save all projects"}</button>}
          {view && <button className="btn" onClick={exportCsv} disabled={busy}>Export CSV</button>}
          {view && <button className="btn" onClick={printReport} disabled={busy}>🖨 Print report</button>}
          {view && !view.isSaved && canEdit && (
            <button className="btn" onClick={save} disabled={saving || busy}>{saving ? "Saving…" : saved ? "Save report (replace saved copy)" : "Save report"}</button>
          )}
        </div>
        {busy && <div style={{ fontSize: 13, color: "#2563eb", marginTop: 10 }}>Checked {progress.done} of {progress.total} members…</div>}
        <div style={{ fontSize: 12, color: "#888", marginTop: 10 }}>
          {eligible.length} member{eligible.length === 1 ? "" : "s"} will be checked. {countsText(wiki)}, using UTC calendar months.
          Edits to pages that were later deleted are not counted. Each project has its own threshold ({WIKIS.map(w => `${w.label} ${w.threshold} ${w.unit}`).join(", ")}).
          {eventsOnly && <> <strong>Kilimanjaro events only:</strong> a member's edit counts only if they joined the event on the Outreach Dashboard and made it between the event's start and end.
            {" "}{monthEvents.length === 0 ? `No Kilimanjaro events in ${monthLabel(month)} — everyone will have 0.` : `${monthEvents.length} event${monthEvents.length === 1 ? "" : "s"} in ${monthLabel(month)}: ${monthEvents.map(w => w.event.title).join(", ")}.`}</>}
        </div>
      </div>

      {error && <div className="alert alert-error">{error}</div>}
      {view?.partial && (
        <div className="alert alert-warn">{monthLabel(month)} isn't finished yet. These are the counts so far.</div>
      )}

      {!view ? (
        <div className="panel"><div className="empty">No report for {scopeName}, {monthLabel(month)} yet. Click "Fetch from {wikiLabel(wiki)}" to count contributions.</div></div>
      ) : (
        <>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12, fontSize: 13, flexWrap: "wrap" }}>
            {view.isSaved ? (
              <span className="badge badge-green">Saved{view.saved.generatedBy ? ` by ${view.saved.generatedBy}` : ""}{view.saved.generatedAt ? ` on ${view.saved.generatedAt.slice(0, 10)}` : ""}</span>
            ) : (
              <span className="badge badge-amber">Not saved yet</span>
            )}
            <span className={`badge ${eventsOnly ? "badge-blue" : "badge-gray"}`}>{scopeLabel(scope)}</span>
            <span style={{ color: "#666" }}>Rule: active if ≥ {view.threshold} different {unit} in {monthLabel(month)}{eventsOnly ? " (in Kilimanjaro events)" : ""}; still editing if ≥ {STILL_EDITING_MIN}</span>
          </div>

          {eventsOnly && (
            <div className="panel" style={{ marginBottom: 16, padding: "12px 16px" }}>
              <div style={{ fontSize: 12, fontWeight: 600, color: "#666", marginBottom: 6 }}>Events counted in {monthLabel(month)}</div>
              {(view.events || []).length === 0 ? <div style={{ fontSize: 13, color: "#888" }}>No Kilimanjaro events this month.</div> : (
                <div style={{ display: "flex", flexDirection: "column", gap: 4, fontSize: 13 }}>
                  {view.events.map(ev => (
                    <div key={ev.slug}>
                      <a href={courseUrl(ev.slug)} target="_blank" rel="noopener noreferrer" style={{ color: "#2563eb", fontWeight: 500 }}>{ev.title}</a>
                      <span style={{ color: "#888" }}> · {dateRange(ev.start, ev.end)} · {ev.members} member{ev.members === 1 ? "" : "s"} joined
                        {ev.viaForm > 0 && ` (${ev.viaForm} only on our registration form)`}
                        {ev.notMembers > 0 && ` · ${ev.notMembers} not in the members list`}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {eventsOnly && (
            <NotMembersPanel people={view.notMembers} members={community} nameFor={nameFor} canEdit={canEdit} profile={profile} showToast={showToast} wiki={wiki} addMembers={addMembers} earlier={earlier}
              title="Joined our events but not in the members list"
              note={`These people joined ${monthLabel(month)}'s Kilimanjaro events but aren't community members, so they are not in the report above. Counts are their edits during the events. Add them, then click "Fetch" again to include them.`} />
          )}

          {best.length > 0 && (
            <div className="panel" style={{ border: "2px solid #d97706", background: "#fffaf0", marginBottom: 16 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#b45309", letterSpacing: 1, textTransform: "uppercase" }}>★ Best contributor of the month{best.length > 1 ? " (shared)" : ""}</div>
              <div style={{ fontSize: 20, fontWeight: 700, color: "#1c2b1e", marginTop: 4 }}>{best.map(b => b.name).join(" & ")}</div>
              <div style={{ fontSize: 13, color: "#666" }}>{best[0].articles} different {unit} in {monthLabel(month)}{view.partial ? " so far" : ""} · {best.map(b => b.username).join(", ")}</div>
            </div>
          )}

          <div className="card-grid">
            {[
              ["Members checked",            memberCount,               "#1c2b1e"],
              [`Active (≥${view.threshold})`, activeCount,               "#2d7a4f"],
              [`Still editing (≥${STILL_EDITING_MIN})`, editingCount,      "#2563eb"],
              ["Not editing",                memberCount - editingCount, "#d97706"],
              ["Active rate",                pctText(activeCount, memberCount), "#1c2b1e"],
            ].map(([label, value, color]) => (
              <div key={label} className="stat-card">
                <div className="stat-label">{label}</div>
                <div className="stat-value" style={{ color }}>{value}</div>
              </div>
            ))}
          </div>

          <MonthlyNewsPanel rows={view.rows} month={month} wiki={wiki} eventsOnly={eventsOnly} orgName={org.orgName} threshold={view.threshold} partial={view.partial} />
          <AllProjectsPanel reports={monthProjects} month={month} eventsOnly={eventsOnly} orgName={org.orgName} />

          <div className="panel" style={{ padding: 0 }}>
            {view.rows.length === 0 ? <div className="empty">No members in this report.</div> : (
              <div style={{ overflowX: "auto" }}>
                <table>
                  <thead><tr><th>#</th><th>Name</th><th>Username</th><th>Different {unit}</th><th>Total edits</th><th>Progress to {view.threshold}</th><th>Status</th></tr></thead>
                  <tbody>
                    {view.rows.map((r, i) => (
                      <tr key={r.memberId || r.username}>
                        <td style={{ fontSize: 12, color: "#888" }}>{i + 1}</td>
                        <td style={{ fontWeight: 500 }}>{r.name}{best.includes(r) && <span title="Best contributor of the month" style={{ color: "#d97706", marginLeft: 4 }}>★</span>}
                          {r.formOnly && <span className="badge badge-gray" style={{ marginLeft: 6, fontSize: 10 }} title="Joined through our registration form, not the Outreach Dashboard — ask them to join the dashboard so the Foundation's numbers include them">form only</span>}</td>
                        <td style={{ fontSize: 12 }}><a href={contribsLink(wiki, r.username)} target="_blank" rel="noopener noreferrer" style={{ color: "#2563eb" }}>{r.username}</a></td>
                        <td style={{ fontWeight: 600 }}>{r.articles}</td>
                        <td style={{ fontSize: 12 }}>{r.edits}</td>
                        <td style={{ minWidth: 120 }}>
                          <div className="progress-bar">
                            <div style={{ height: "100%", width: `${Math.min(100, (r.articles / (view.threshold || 1)) * 100)}%`, background: r.active ? "#4a9e6b" : "#d97706" }} />
                          </div>
                        </td>
                        <td>{r.active ? <span className="badge badge-green">Active</span>
                          : isEditing(r) ? <span className="badge badge-blue">Still editing</span>
                          : <span className="badge badge-amber">Not editing</span>}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

// ── History tab ────────────────────────────────────────────────────────────────
function History({ reports }) {
  const [wiki, setWiki] = useState(DEFAULT_WIKI);
  const forWiki = reports.filter(r => r.wiki === wiki);
  const byMonth = Object.fromEntries(forWiki.map(r => [r.month, r]));
  const months  = previousMonths(currentMonth(), 12);
  const maxMembers = Math.max(1, ...months.map(m => byMonth[m]?.memberCount || 0));
  const CHART_H = 140;
  const sorted = [...forWiki].sort((a, b) => b.month.localeCompare(a.month));

  return (
    <div>
      <div className="panel" style={{ marginBottom: 20 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12, flexWrap: "wrap", marginBottom: 14 }}>
          <div className="panel-title" style={{ margin: 0 }}>Last 12 months</div>
          <div className="field" style={{ margin: 0, minWidth: 200 }}><WikiSelect value={wiki} onChange={setWiki} /></div>
        </div>
        <div style={{ display: "flex", gap: 16, fontSize: 12, color: "#666", marginBottom: 10 }}>
          <span><span style={{ display: "inline-block", width: 10, height: 10, background: "#c9d8cd", borderRadius: 2, marginRight: 4 }} />Members checked</span>
          <span><span style={{ display: "inline-block", width: 10, height: 10, background: "#2563eb", borderRadius: 2, marginRight: 4 }} />Still editing</span>
          <span><span style={{ display: "inline-block", width: 10, height: 10, background: "#2d7a4f", borderRadius: 2, marginRight: 4 }} />Active</span>
        </div>
        <div style={{ overflowX: "auto" }}>
          <div style={{ display: "flex", alignItems: "flex-end", gap: 8, minWidth: 560, height: CHART_H + 36 }}>
            {months.map(m => {
              const r = byMonth[m];
              const mh = r ? (r.memberCount / maxMembers) * CHART_H : 0;
              const ah = r ? (r.activeCount / maxMembers) * CHART_H : 0;
              const eh = r ? (reportEditing(r) / maxMembers) * CHART_H : 0;
              return (
                <div key={m} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}
                  title={r ? `${monthLabel(m)}: ${r.activeCount} active, ${reportEditing(r)} still editing, of ${r.memberCount}` : `${monthLabel(m)}: no saved report`}>
                  <div style={{ fontSize: 11, fontWeight: 600, color: "#2d7a4f", height: 14 }}>{r ? r.activeCount : ""}</div>
                  <div style={{ display: "flex", alignItems: "flex-end", gap: 2, height: CHART_H }}>
                    <div style={{ width: 10, height: mh, background: "#c9d8cd", borderRadius: "2px 2px 0 0" }} />
                    <div style={{ width: 10, height: eh, background: "#2563eb", borderRadius: "2px 2px 0 0" }} />
                    <div style={{ width: 10, height: ah, background: "#2d7a4f", borderRadius: "2px 2px 0 0" }} />
                  </div>
                  <div style={{ fontSize: 10, color: r ? "#666" : "#bbb", whiteSpace: "nowrap" }}>{monthLabel(m)}</div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      <div className="panel" style={{ padding: 0 }}>
        {sorted.length === 0 ? <div className="empty">No saved reports for {wikiLabel(wiki)} yet. Save one from the Report tab.</div> : (
          <div style={{ overflowX: "auto" }}>
            <table>
              <thead><tr><th>Month</th><th>Members</th><th>Still editing</th><th>Active</th><th>Different {wikiInfo(wiki).unit}</th><th>{cap(wikiInfo(wiki).newUnit)}</th><th>Rate</th><th>Best contributor</th><th>Rule</th><th>Saved by</th></tr></thead>
              <tbody>
                {sorted.map(r => (
                  <tr key={r.id}>
                    <td style={{ fontWeight: 500 }}>{monthLabel(r.month)}{r.partial && <span className="badge badge-amber" style={{ marginLeft: 6 }}>so far</span>}</td>
                    <td>{r.memberCount}</td>
                    <td style={{ color: "#2563eb" }}>{reportEditing(r)}</td>
                    <td style={{ fontWeight: 600, color: "#2d7a4f" }}>{r.activeCount}</td>
                    {(() => { const nw = monthlyNews(r.rows); return (<>
                      <td>{nw.articles.toLocaleString()}</td>
                      <td style={{ color: "#7c3aed" }}>{nw.detailed ? nw.created.toLocaleString() : "—"}</td>
                    </>); })()}
                    <td>{pctText(r.activeCount, r.memberCount)}</td>
                    <td style={{ fontSize: 12 }}>{(() => { const b = bestContributors(r.rows || []); return b.length ? <>★ {b.map(x => x.name).join(" & ")} <span style={{ color: "#888" }}>({b[0].articles})</span></> : ""; })()}</td>
                    <td style={{ fontSize: 12 }}>≥ {r.threshold} {wikiInfo(wiki).unit}</td>
                    <td style={{ fontSize: 12 }}>{r.generatedBy || ""}{r.generatedAt ? `, ${r.generatedAt.slice(0, 10)}` : ""}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

// People from another list (volunteers / event participants) whose Wikipedia
// username isn't in the community list yet — one entry per username.
function notYetMembers(list, existing, source) {
  const seen = new Set([...existing].map(u => u.toLowerCase()));   // capitals ignored
  const out = [];
  for (const v of list) {
    const u = normalizeUsername(v.wikimediaUsername);
    if (!u || seen.has(u.toLowerCase())) continue;
    seen.add(u.toLowerCase());
    out.push({ name: (v.name || "").trim() || u, wikimediaUsername: u, isActive: true, source });
  }
  return out;
}

// ── Year summary tab ───────────────────────────────────────────────────────────
const LABEL_BADGE = { active: "badge-green", retained: "badge-blue", participated: "badge-gray" };

function MonthStrip({ months, byMonth, covered }) {
  return (
    <div style={{ display: "flex", gap: 2 }}>
      {months.map(m => {
        const c = byMonth[m];
        const has = covered.has(m);
        const bg = c?.active ? "#2d7a4f" : c?.editing ? "#2563eb" : has ? "#e5e5e0" : "transparent";
        const tip = !has ? `${monthLabel(m)}: no saved report`
          : `${monthLabel(m)}: ${c ? c.articles : 0} article${c?.articles === 1 ? "" : "s"}${c?.active ? " (active)" : c?.editing ? " (still editing)" : ""}`;
        return <div key={m} title={tip} style={{ width: 10, height: 14, borderRadius: 2, background: bg, border: has ? "none" : "1px dashed #ccc", boxSizing: "border-box" }} />;
      })}
    </div>
  );
}

function YearSummary({ members, reports, scope, currentGrant, profile, org, signature, returning = new Set() }) {
  const base = useMemo(() => defaultPeriod(currentGrant), [currentGrant]);
  const qs   = useMemo(() => quarters(base.start, base.end), [base]);
  const [mode,   setMode]   = useState("year");      // "year" | "Q1".. | "custom"
  const [custom, setCustom] = useState(base);
  const [wiki,   setWiki]   = useState("all");
  const [search, setSearch] = useState("");

  const period = mode === "year" ? base
    : mode === "custom" ? custom
    : (qs.find(q => q.label === mode) || base);

  // Members left out of reports ("In reports" unticked) only appear if they have history.
  const inReports = useMemo(() => members.filter(m => m.isActive !== false), [members]);
  const summary = useMemo(
    () => buildYearSummary(reports, inReports, { start: period.start, end: period.end, wiki }),
    [reports, inReports, period.start, period.end, wiki],
  );
  const quarterRows = useMemo(
    () => qs.map(q => ({ q, s: buildYearSummary(reports, inReports, { start: q.start, end: q.end, wiki }) })),
    [qs, reports, inReports, wiki],
  );
  const covered = new Set(summary.covered);
  const t = summary.totals;
  const range = (s, e) => s === e ? monthLabel(s) : `${monthLabel(s)} – ${monthLabel(e)}`;

  const q = search.toLowerCase();
  const rows = summary.rows.filter(r => !q || r.name.toLowerCase().includes(q) || r.username.toLowerCase().includes(q));

  const eventsOnly = scope === "events";
  const wikiName = `${wiki === "all" ? "All wikis" : wikiLabel(wiki)}${eventsOnly ? " — Kilimanjaro events only" : ""}`;

  const printSummary = async () => {
    openPrintWindow(yearReportHtml({ summary, start: period.start, end: period.end, wikiLabel: wikiName, quarterRows: mode === "year" ? quarterRows : [], ...org }));
    await addAudit(profile, AUDIT_ACTIONS.EXPORT, "contributors", {
      recordTitle: `Summary ${period.start} to ${period.end}`, details: "Printed contributor summary",
    });
  };

  const printCertificates = async (list) => {
    if (summary.missing.length > 0 && !window.confirm(`${summary.missing.length} month${summary.missing.length === 1 ? " has" : "s have"} no saved report in this period, so some certificates may show lower numbers. Print anyway?`)) return;
    if (!signature.signatureImage && !window.confirm("No coordinator signature has been uploaded yet (Settings → Certificate signature), so the signature line will be blank. Print anyway?")) return;
    openPrintWindow(certificatesHtml(list, { ...org, start: period.start, end: period.end, signature, art: certificateArt(), eventsOnly }));
    await addAudit(profile, AUDIT_ACTIONS.EXPORT, "contributors", {
      recordTitle: list.length === 1 ? list[0].name : `${list.length} certificates`,
      details: `Printed ${list.length} community member certificate${list.length === 1 ? "" : "s"} (${period.start} to ${period.end}, ${scopeLabel(scope)})`,
    });
  };

  const exportCsv = async () => {
    const tag = mode === "year" ? "year" : mode === "custom" ? "custom" : mode;
    downloadCsv(`contributors-${tag}-${period.start}-to-${period.end}${eventsOnly ? "-kilimanjaro-events" : ""}.csv`, yearSummaryToCsv(summary));
    await addAudit(profile, AUDIT_ACTIONS.EXPORT, "contributors", {
      recordTitle: `Summary ${period.start} to ${period.end}`, details: `Exported contributor summary (${summary.rows.length} people)`,
    });
  };

  return (
    <div>
      <div className="panel" style={{ marginBottom: 20 }}>
        <div className="form-grid">
          <div className="field"><label>Period</label>
            <select value={mode} onChange={e => setMode(e.target.value)}>
              <option value="year">Full year ({range(base.start, base.end)})</option>
              {qs.map(x => <option key={x.label} value={x.label}>{x.label} ({range(x.start, x.end)})</option>)}
              <option value="custom">Custom…</option>
            </select>
          </div>
          {mode === "custom" && (
            <>
              <div className="field"><label>From</label><input type="month" value={custom.start} onChange={e => e.target.value && setCustom(c => ({ ...c, start: e.target.value }))} /></div>
              <div className="field"><label>To</label><input type="month" value={custom.end} onChange={e => e.target.value && setCustom(c => ({ ...c, end: e.target.value }))} /></div>
            </>
          )}
          <div className="field"><label>Wiki</label>
            <select value={wiki} onChange={e => setWiki(e.target.value)}>
              <option value="all">All wikis</option>
              {WIKIS.map(w => <option key={w.id} value={w.id}>{w.label}</option>)}
            </select>
          </div>
        </div>
        <div style={{ fontSize: 12, color: "#888", marginTop: 8 }}>
          {currentGrant?.startDate && currentGrant?.endDate
            ? `Full year follows the selected grant (${currentGrant.startDate} to ${currentGrant.endDate}). Quarters count from its first month.`
            : "No grant dates set, so the full year is the last 12 finished months."}
          {" "}Built from saved monthly reports counted as <strong>{scopeLabel(scope).toLowerCase()}</strong>. Unfinished months are left out.
        </div>
      </div>

      {/* Quarter by quarter */}
      {qs.length > 1 && (
        <div className="panel" style={{ padding: 0, marginBottom: 20 }}>
          <div className="panel-title" style={{ padding: "14px 16px 0" }}>Quarter by quarter</div>
          <div style={{ overflowX: "auto" }}>
            <table>
              <thead><tr><th>Quarter</th><th>Months saved</th><th>Still editing (1+ month)</th><th>Active contributors</th><th>Edited every month</th><th>Articles</th><th></th></tr></thead>
              <tbody>
                {quarterRows.map(({ q: x, s }) => (
                  <tr key={x.label} style={mode === x.label ? { background: "#f0f8f3" } : undefined}>
                    <td style={{ fontWeight: 600 }}>{x.label} <span style={{ fontWeight: 400, fontSize: 12, color: "#888" }}>{range(x.start, x.end)}</span></td>
                    <td style={{ fontSize: 12 }}>
                      {s.covered.length} of {x.months.length}
                      {s.missing.length > 0 && <span className="badge badge-amber" style={{ marginLeft: 6 }}>{s.missing.length} missing</span>}
                      {s.future.length > 0 && s.missing.length === 0 && s.covered.length < x.months.length && <span style={{ marginLeft: 6, color: "#aaa" }}>not finished</span>}
                    </td>
                    <td style={{ color: "#2563eb", fontWeight: 600 }}>{s.totals.editedOnce}</td>
                    <td style={{ color: "#2d7a4f", fontWeight: 600 }}>{s.totals.active}</td>
                    <td>{s.rows.filter(r => r.monthsEditing >= x.months.length && x.months.length > 0).length}</td>
                    <td>{s.totals.articles.toLocaleString()}</td>
                    <td><button className="btn btn-sm" onClick={() => setMode(x.label)}>View</button></td>
                  </tr>
                ))}
                <tr style={{ borderTop: "2px solid #e8e8e4", background: mode === "year" ? "#f0f8f3" : undefined }}>
                  <td style={{ fontWeight: 700 }}>Full year</td>
                  {(() => { const s = buildYearSummary(reports, inReports, { start: base.start, end: base.end, wiki }); return (<>
                    <td style={{ fontSize: 12 }}>{s.covered.length} of {s.months.length}</td>
                    <td style={{ color: "#2563eb", fontWeight: 700 }}>{s.totals.editedOnce}</td>
                    <td style={{ color: "#2d7a4f", fontWeight: 700 }}>{s.totals.active}</td>
                    <td style={{ fontSize: 12, color: "#666" }}>Retained (3+ months): <strong>{s.totals.retained}</strong></td>
                    <td style={{ fontWeight: 700 }}>{s.totals.articles.toLocaleString()}</td>
                  </>); })()}
                  <td><button className="btn btn-sm" onClick={() => setMode("year")}>View</button></td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      )}

      {summary.bestByMonth.some(b => b.people.length) && (
        <div className="panel" style={{ border: "1px solid #f0d5b0", background: "#fffaf0", marginBottom: 20 }}>
          <div className="panel-title" style={{ color: "#b45309" }}>★ Best contributor of each month</div>
          {summary.bestByMonth.some(b => b.byPoints) && (
            <div style={{ fontSize: 12, color: "#888", marginTop: -6, marginBottom: 10 }}>
              By points across our four projects: reaching a project's active level = {POINTS_PER_LEVEL} points
              ({POINTS_WIKIS.map(id => `${thresholdFor(id)} ${wikiInfo(id).unit} on ${wikiInfo(id).label}`).join(" = ")}).
            </div>
          )}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(180px, 1fr))", gap: 10 }}>
            {summary.bestByMonth.map(b => (
              <div key={b.month} style={{ fontSize: 13 }}>
                <div style={{ fontSize: 11, color: "#888" }}>{monthLabel(b.month)}</div>
                <div style={{ fontWeight: 600 }}>{b.people.length ? b.people.map(p => p.name).join(" & ") : "No edits"}</div>
                {b.byPoints
                  ? b.points > 0 && <div style={{ fontSize: 12, color: "#b45309" }}>{b.points.toLocaleString()} points</div>
                  : b.articles > 0 && <div style={{ fontSize: 12, color: "#b45309" }}>{b.articles} articles</div>}
              </div>
            ))}
          </div>
        </div>
      )}

      {summary.missing.length > 0 && (
        <div className="alert alert-warn">
          No saved report for {summary.missing.map(monthLabel).join(", ")}. Fetch and save {summary.missing.length === 1 ? "that month" : "those months"} on the Report tab, or this summary will undercount.
        </div>
      )}

      <div className="card-grid">
        {[
          ["People",                         t.people,       "#1c2b1e"],
          ...(currentGrant ? [["Returning from earlier grants", summary.rows.filter(r => returning.has(r.username)).length, "#2563eb"]] : []),
          ["Active contributors",            t.active,       "#2d7a4f"],
          [`Retained (${RETAINED_MIN_MONTHS}+ months editing)`, t.retained, "#2563eb"],
          ["Still editing (at least 1 month)", t.editedOnce, "#2563eb"],
          ["Participated only",              t.participated, "#d97706"],
          ["Months saved",                   `${summary.covered.length} of ${summary.months.length}`, "#1c2b1e"],
        ].map(([label, value, color]) => (
          <div key={label} className="stat-card">
            <div className="stat-label">{label}</div>
            <div className="stat-value" style={{ color }}>{value}</div>
          </div>
        ))}
      </div>

      <div style={{ display: "flex", gap: 10, alignItems: "center", marginBottom: 12, flexWrap: "wrap" }}>
        <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search name or username..." style={{ flex: 1, minWidth: 200, fontSize: 13 }} />
        <button className="btn" onClick={exportCsv} disabled={summary.rows.length === 0}>Export CSV</button>
        <button className="btn" onClick={printSummary} disabled={summary.rows.length === 0}>🖨 Print summary</button>
        <button className="btn btn-primary" onClick={() => printCertificates(rows)} disabled={rows.length === 0}>
          Print {rows.length} certificate{rows.length === 1 ? "" : "s"}{search ? " (filtered)" : ""}
        </button>
      </div>

      <div className="panel" style={{ padding: 0 }}>
        {rows.length === 0 ? (
          <div className="empty">{summary.rows.length === 0 ? "No members or saved reports for this period yet." : "No one matches your search."}</div>
        ) : (
          <div style={{ overflowX: "auto" }}>
            <table>
              <thead><tr><th>#</th><th>Name</th><th>Username</th><th>Recognition</th><th>Months active</th><th>Months still editing</th><th>Total articles</th><th>Best month</th><th>Month by month</th><th></th></tr></thead>
              <tbody>
                {rows.map((r, i) => (
                  <tr key={r.username}>
                    <td style={{ fontSize: 12, color: "#888" }}>{i + 1}</td>
                    <td style={{ fontWeight: 500 }}>{r.name}{r.bestOfMonth.length > 0 && <span title={`Best contributor: ${r.bestOfMonth.map(m => monthLabel(m)).join(", ")}`} style={{ color: "#d97706", marginLeft: 4 }}>★</span>}
                      {returning.has(r.username) && <span className="badge badge-blue" style={{ marginLeft: 6, fontSize: 10 }} title="Also a member in an earlier grant — counts as retention">Returning</span>}</td>
                    <td style={{ fontSize: 12 }}>{r.username}</td>
                    <td><span className={`badge ${LABEL_BADGE[r.label]}`}>{YEAR_LABELS[r.label]}</span></td>
                    <td>{r.monthsActive}</td>
                    <td>{r.monthsEditing}</td>
                    <td style={{ fontWeight: 600 }}>{r.totalArticles.toLocaleString()}</td>
                    <td style={{ fontSize: 12 }}>{r.bestMonth.month ? `${monthLabel(r.bestMonth.month)} (${r.bestMonth.articles})` : ""}</td>
                    <td><MonthStrip months={summary.months} byMonth={r.byMonth} covered={covered} /></td>
                    <td><button className="btn btn-sm" onClick={() => printCertificates([r])}>Certificate</button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <div style={{ fontSize: 12, color: "#888", marginTop: 10 }}>
        <strong>Active contributor</strong>: reached the active level on any project in at least one month ({WIKIS.map(w => `${w.label} ${w.threshold}+ ${w.unit}`).join(", ")}; the threshold saved with each report counts).
        {" "}<strong>Retained</strong>: still editing (1+ article) in {RETAINED_MIN_MONTHS} or more months.
        {" "}Total articles adds the monthly counts, so an article edited in two different months counts twice.
        {" "}Strip: <span style={{ color: "#2d7a4f" }}>■</span> active, <span style={{ color: "#2563eb" }}>■</span> still editing, <span style={{ color: "#bbb" }}>■</span> no edits, dashed = no saved report.
      </div>
    </div>
  );
}

// ── Events tab — Kilimanjaro events (Outreach Dashboard courses) ───────────────
function Events({ events, members, forms, profile, canEdit, isAdmin, showToast, nameFor, addMembers, earlier }) {
  const [links,   setLinks]   = useState("");
  const [busy,    setBusy]    = useState(false);
  const [errors,  setErrors]  = useState([]);
  const [rootUrl, setRootUrl] = useState(DEFAULT_ACTIVITIES_PAGE);
  const [found,   setFound]   = useState(null);   // discovered event pages
  const [finding, setFinding] = useState("");     // progress text
  const [picked,  setPicked]  = useState({});     // title → true
  const [pasted,  setPasted]  = useState({});     // title → dashboard link typed by hand

  const addedIds = useMemo(() => new Set(events.map(e => e.id)), [events]);
  const [regs, setRegs] = useState([]);
  useEffect(() => { getAllRegistrations().then(setRegs).catch(() => {}); }, []);
  const formTitle = (id) => forms.find(f => f.id === id)?.title || "(deleted form)";
  const outsiders = useMemo(() => {
    const byEvent = Object.fromEntries(events.map(ev => [ev.id, formJoiners(regs.filter(r => (ev.formIds || []).includes(r.formId)))]));
    const formSet = new Set(Object.values(byEvent).flat());
    const dashSet = new Set(events.flatMap(ev => ev.participants || []));
    return joinedNotMembers(events, members.map(m => m.wikimediaUsername), byEvent)
      .map(p => ({ ...p, formOnly: formSet.has(p.username) && !dashSet.has(p.username) }));
  }, [events, regs, members]);

  const setForms = async (ev, formIds) => {
    await saveContributorEvent(ev.id, { formIds });
    await addAudit(profile, AUDIT_ACTIONS.UPDATE, "contributors", {
      targetId: ev.id, recordTitle: ev.title, details: `Registration forms linked: ${formIds.map(formTitle).join(", ") || "none"}`,
    });
  };

  const memberSet = useMemo(
    () => new Set(members.map(m => normalizeUsername(m.wikimediaUsername)).filter(Boolean)),
    [members],
  );

  // Fetch from the dashboard and save. Returns an error line or "".
  const saveOne = async (slug, extra = {}) => {
    try {
      const c = await fetchCourse(slug);
      await saveContributorEvent(eventDocId(slug), { ...c, ...extra, refreshedAt: new Date().toISOString() });
      return "";
    } catch (e) {
      return `${slug}: ${e.message}`;
    }
  };

  const addEvents = async () => {
    const lines = links.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    const slugs = [...new Set(lines.map(parseCourseSlug).filter(Boolean))];
    const bad = lines.filter(l => !parseCourseSlug(l)).map(l => `${l}: not an Outreach Dashboard event link`);
    if (slugs.length === 0) { setErrors(bad.length ? bad : ["Paste at least one link."]); return; }
    setBusy(true);
    const failed = [...bad];
    let added = 0;
    for (const slug of slugs) {
      const err = await saveOne(slug);
      if (err) failed.push(err); else added++;
    }
    setBusy(false);
    setErrors(failed);
    if (added) {
      await addAudit(profile, AUDIT_ACTIONS.CREATE, "contributors", { details: `Added ${added} Kilimanjaro event${added === 1 ? "" : "s"} for contribution counting` });
      setLinks(failed.length ? links : "");
      showToast(`Added ${added} event${added === 1 ? "" : "s"}.`);
    }
  };

  const refreshAll = async () => {
    setBusy(true);
    const failed = [];
    for (const ev of events) {
      const err = await saveOne(ev.slug, { wikiPage: ev.wikiPage || "", program: ev.program || "" });
      if (err) failed.push(err);
    }
    setBusy(false);
    setErrors(failed);
    if (failed.length < events.length) showToast("Events refreshed from the Outreach Dashboard.");
  };

  // Follow the activities page → programs → sub-events, then match each event
  // to the dashboard course with the same name.
  const findEvents = async () => {
    setErrors([]);
    setFound(null);
    setFinding("Reading the activities page and every program's sub-events…");
    try {
      const pages = await discoverEventPages(rootUrl);
      const list = [];
      for (let i = 0; i < pages.length; i++) {
        setFinding(`Matching dashboard courses… ${i + 1} of ${pages.length}`);
        let slug = "";
        try { slug = await findCourseForEvent(pages[i].name); } catch { /* leave unmatched */ }
        list.push({ ...pages[i], slug });
      }
      const shown = list.filter(e => !e.isParent || e.slug);
      setFound(shown);
      setPicked(Object.fromEntries(shown.filter(e => e.slug && !addedIds.has(eventDocId(e.slug))).map(e => [e.title, true])));
      setPasted({});
    } catch (e) {
      setErrors([`Could not read ${rootUrl}: ${e.message}`]);
    } finally {
      setFinding("");
    }
  };

  const slugFor = (ev) => ev.slug || parseCourseSlug(pasted[ev.title]);

  const addPicked = async () => {
    const list = (found || []).filter(ev => picked[ev.title] && slugFor(ev));
    if (list.length === 0) return;
    setBusy(true);
    const failed = [];
    let added = 0;
    for (const ev of list) {
      const err = await saveOne(slugFor(ev), { wikiPage: ev.title, program: ev.program });
      if (err) failed.push(err); else added++;
    }
    setBusy(false);
    setErrors(failed);
    if (added) {
      await addAudit(profile, AUDIT_ACTIONS.CREATE, "contributors", { details: `Added ${added} Kilimanjaro event${added === 1 ? "" : "s"} from ${rootUrl}` });
      setPicked({});
      showToast(`Added ${added} event${added === 1 ? "" : "s"}.`);
    }
  };

  const pickedCount = (found || []).filter(ev => picked[ev.title] && slugFor(ev)).length;

  const del = async (ev) => {
    if (!window.confirm(`Remove "${ev.title}" from Kilimanjaro events? Saved reports keep their numbers; new reports won't count this event.`)) return;
    await deleteContributorEvent(ev.id);
    await addAudit(profile, AUDIT_ACTIONS.DELETE, "contributors", { targetId: ev.id, recordTitle: ev.title, details: `Removed Kilimanjaro event ${ev.slug}` });
    showToast("Event removed.");
  };

  const sorted = [...events].sort((a, b) => String(b.start).localeCompare(String(a.start)));

  return (
    <div>
      <div className="alert alert-info">
        These are the events used when counting <strong>Kilimanjaro events only</strong>. A member's edit counts if they joined the event
        (on the Outreach Dashboard, <strong>or</strong> on one of our registration forms linked below, unless marked absent) and made it between
        the event's start and end. Edits in other groups' events, or outside our event dates, are not counted.
        {" "}<strong>Whole wiki</strong> reports ignore this list.
      </div>

      {canEdit && (
        <div className="panel" style={{ marginBottom: 20 }}>
          <div className="panel-title">Find events from our activities page</div>
          <div className="field">
            <label>Activities page on Wikipedia</label>
            <input value={rootUrl} onChange={e => setRootUrl(e.target.value)} spellCheck={false} />
          </div>
          <div className="btn-row">
            <button className="btn btn-primary" onClick={findEvents} disabled={!!finding || busy || !rootUrl.trim()}>{finding ? "Finding…" : "Find events"}</button>
            {found && <button className="btn" onClick={addPicked} disabled={busy || pickedCount === 0}>{busy ? "Adding…" : `Add ${pickedCount} selected`}</button>}
          </div>
          {finding && <div style={{ fontSize: 13, color: "#2563eb", marginTop: 10 }}>{finding}</div>}
          <div style={{ fontSize: 12, color: "#888", marginTop: 8 }}>
            Follows every program on the page down to its last sub-event (including the program's navigation tabs), then looks for the
            Outreach Dashboard course with the same name. If an event's course has a different name, paste its dashboard link in the row.
          </div>

          {found && (found.length === 0 ? <div className="empty">No event pages found under this page.</div> : (
            <div style={{ overflowX: "auto", marginTop: 12 }}>
              <table>
                <thead><tr><th></th><th>Program</th><th>Event</th><th>Dashboard course</th></tr></thead>
                <tbody>
                  {found.map(ev => {
                    const slug = slugFor(ev);
                    const added = slug && addedIds.has(eventDocId(slug));
                    return (
                      <tr key={ev.title} style={added ? { color: "#999" } : undefined}>
                        <td><input type="checkbox" checked={!!picked[ev.title] && !!slug} disabled={!slug || added}
                          onChange={e => setPicked(p => ({ ...p, [ev.title]: e.target.checked }))} /></td>
                        <td style={{ fontSize: 12 }}>{ev.program}</td>
                        <td style={{ fontSize: 13 }}>
                          <a href={`https://sw.wikipedia.org/wiki/${encodeURIComponent(ev.title.replace(/ /g, "_"))}`} target="_blank" rel="noopener noreferrer" style={{ color: ev.exists ? "#2563eb" : "#c0392b" }}>{ev.name}</a>
                          {!ev.exists && <span className="badge badge-gray" style={{ marginLeft: 6 }}>page not created yet</span>}
                        </td>
                        <td style={{ fontSize: 12 }}>
                          {added ? <span className="badge badge-green">Already added</span>
                            : ev.slug ? <a href={courseUrl(ev.slug)} target="_blank" rel="noopener noreferrer" style={{ color: "#2563eb" }}>{ev.slug.split("/")[1].replace(/_/g, " ")}</a>
                            : <input value={pasted[ev.title] || ""} placeholder="No course with this name — paste dashboard link" spellCheck={false}
                                style={{ fontSize: 12, minWidth: 260, borderColor: pasted[ev.title] && !parseCourseSlug(pasted[ev.title]) ? "#c0392b" : undefined }}
                                onChange={e => { const v = e.target.value; setPasted(p => ({ ...p, [ev.title]: v })); setPicked(p => ({ ...p, [ev.title]: !!parseCourseSlug(v) })); }} />}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          ))}
        </div>
      )}

      {canEdit && (
        <div className="panel" style={{ marginBottom: 20 }}>
          <div className="panel-title">Add events by dashboard link</div>
          <div className="field">
            <label>Outreach Dashboard event links, one per line</label>
            <textarea rows={4} value={links} onChange={e => setLinks(e.target.value)} spellCheck={false}
              placeholder={"https://outreachdashboard.wmflabs.org/courses/Wikimedia_Community_Kilimanjaro/January_2026_Training"} />
          </div>
          <div className="btn-row">
            <button className="btn btn-primary" onClick={addEvents} disabled={busy || !links.trim()}>{busy ? "Working…" : "Add events"}</button>
            {events.length > 0 && <button className="btn" onClick={refreshAll} disabled={busy}>Refresh all from dashboard</button>}
          </div>
          <div style={{ fontSize: 12, color: "#888", marginTop: 8 }}>
            Where to find the link: on the Wikipedia event page open the event details (Maelezo ya tukio), check that contribution tracking is on,
            and follow its Programs &amp; Events Dashboard link. Each event needs its own dashboard course.
          </div>
        </div>
      )}

      {errors.length > 0 && (
        <div className="alert alert-warn" style={{ display: "flex", justifyContent: "space-between", gap: 12 }}>
          <span>Could not add or refresh: {errors.map((e, i) => <div key={i}>{e}</div>)}</span>
          <button className="btn btn-sm" onClick={() => setErrors([])}>Dismiss</button>
        </div>
      )}

      <NotMembersPanel people={outsiders} members={members} nameFor={nameFor} canEdit={canEdit} profile={profile} showToast={showToast} addMembers={addMembers} earlier={earlier}
        title="People in this grant's events who aren't community members yet"
        note={`Everyone who joined this grant's events on the Outreach Dashboard (as of the last refresh) or on a linked registration form, but isn't in the community members list. Their edits aren't counted until you add them. Click "Refresh all from dashboard" first to catch late sign-ups.`} />

      <div className="panel" style={{ padding: 0 }}>
        {sorted.length === 0 ? <div className="empty">No Kilimanjaro events yet. Paste their Outreach Dashboard links above.</div> : (
          <div style={{ overflowX: "auto" }}>
            <table>
              <thead><tr><th>Event</th><th>Program</th><th>Dates</th><th>On dashboard</th><th>Registration forms</th><th>Community members</th><th>Wikipedia event</th><th>Updated</th>{isAdmin && <th></th>}</tr></thead>
              <tbody>
                {sorted.map(ev => {
                  const people = ev.participants || [];
                  const linked = ev.formIds || [];
                  const formPeople = formJoiners(regs.filter(r => linked.includes(r.formId)));
                  const joined = new Set([...people, ...formPeople]);
                  const suggested = forms.filter(f => !linked.includes(f.id) && formMatchesEvent(f, ev));
                  const others = forms.filter(f => !linked.includes(f.id) && !suggested.includes(f));
                  return (
                    <tr key={ev.id}>
                      <td style={{ fontWeight: 500 }}><a href={courseUrl(ev.slug)} target="_blank" rel="noopener noreferrer" style={{ color: "#2563eb" }}>{ev.title}</a></td>
                      <td style={{ fontSize: 12, color: "#666" }}>{ev.program || ""}</td>
                      <td style={{ fontSize: 12 }}>{dateRange(ev.start, ev.end)}</td>
                      <td>{people.length}</td>
                      <td style={{ fontSize: 12, minWidth: 200 }}>
                        {linked.map(id => (
                          <div key={id} style={{ display: "flex", alignItems: "center", gap: 4 }}>
                            <span>{formTitle(id)}</span>
                            {canEdit && <button className="btn btn-sm" style={{ padding: "0 6px" }} title="Unlink" onClick={() => setForms(ev, linked.filter(x => x !== id))}>×</button>}
                          </div>
                        ))}
                        {linked.length > 0 && <div style={{ color: "#888" }}>{formPeople.length} with a username, not absent</div>}
                        {canEdit && suggested.map(f => (
                          <button key={f.id} className="btn btn-sm" style={{ marginTop: 4, display: "block" }} onClick={() => setForms(ev, [...linked, f.id])}
                            title="This form's Wikipedia event link points at this event">+ Link "{f.title}" (suggested)</button>
                        ))}
                        {canEdit && others.length > 0 && (
                          <select value="" style={{ fontSize: 12, marginTop: 4, maxWidth: 220 }} onChange={e => e.target.value && setForms(ev, [...linked, e.target.value])}>
                            <option value="">+ Link a registration form…</option>
                            {others.map(f => <option key={f.id} value={f.id}>{f.title}{f.date ? ` (${f.date})` : ""}</option>)}
                          </select>
                        )}
                      </td>
                      <td title={`${[...joined].filter(u => memberSet.has(u)).length} of ${joined.size} people who joined are community members`}>{[...joined].filter(u => memberSet.has(u)).length}</td>
                      <td style={{ fontSize: 12 }}>{ev.wikiEventId
                        ? <a href={`https://sw.wikipedia.org/wiki/Special:EventDetails/${ev.wikiEventId}`} target="_blank" rel="noopener noreferrer" style={{ color: "#2563eb" }}>EventDetails/{ev.wikiEventId}</a>
                        : <span style={{ color: "#aaa" }}>not linked</span>}</td>
                      <td style={{ fontSize: 12, color: "#888" }}>{(ev.refreshedAt || "").slice(0, 10)}</td>
                      {isAdmin && <td><button className="btn btn-sm btn-danger" onClick={() => del(ev)}>✕</button></td>}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
      <div style={{ fontSize: 12, color: "#888", marginTop: 10 }}>
        "On dashboard" is from the last refresh. Reports always re-check who joined, so late sign-ups still count. Dates are shown in Tanzania time.
        {" "}Link the registration form you used for each event so walk-ins who never joined the dashboard still count — they are tagged "form only" in reports.
      </div>
    </div>
  );
}

// ── Members tab ────────────────────────────────────────────────────────────────
function Members({ members, volunteers, participants, profile, canEdit, isAdmin, showToast, addMembers, returning = new Set(), grantPeople = null, grantsOf = () => [], grantTitle = "", participantName = new Map() }) {
  const [name,     setName]     = useState("");
  const [username, setUsername] = useState("");
  const [bulk,     setBulk]     = useState("");
  const [search,   setSearch]   = useState("");
  const [busy,     setBusy]     = useState(false);
  const [missing,  setMissing]  = useState([]);
  const [projects, setProjects] = useState(null);   // Map<username, [{ host, label, edits }]> — this session only
  const [projBusy, setProjBusy] = useState(null);   // { done, total }
  const [editing,  setEditing]  = useState(null);   // { id, value } — name being edited
  const [onlyCheck, setOnlyCheck] = useState(false); // show only names to check
  const [userCheck, setUserCheck] = useState(null);   // { busy, notFound: Set(username) }
  const [fixUser,  setFixUser]  = useState({});       // memberId → typed username

  const existing = useMemo(
    () => new Set(members.map(m => normalizeUsername(m.wikimediaUsername)).filter(Boolean)),
    [members],
  );

  const importable = useMemo(() => notYetMembers(volunteers, existing, "volunteers"), [volunteers, existing]);
  const importableParticipants = useMemo(() => notYetMembers(participants, existing, "participants"), [participants, existing]);
  const participantsNoUsername = participants.filter(p => !normalizeUsername(p.wikimediaUsername)).length;

  // Warn about usernames that don't exist on Swahili Wikipedia (likely typos)
  const verify = async (usernames) => {
    try {
      const res = await checkUsernames(usernames, WIKIS[0].id);
      setMissing(res.missing);
    } catch {
      setMissing([]);
    }
  };

  const addOne = async () => {
    const u = normalizeUsername(username);
    if (!u) { alert("Wikipedia username is required."); return; }
    const same = members.find(m => userKey(m.wikimediaUsername) === u.toLowerCase());
    if (same) { alert(`${u} is already in the list${same.wikimediaUsername !== u ? ` as ${same.wikimediaUsername}` : ""}.`); return; }
    setBusy(true);
    try {
      const fullName = name.trim() || u;
      await addMembers([{ name: fullName, wikimediaUsername: u, isActive: true, source: "manual" }]);
      await addAudit(profile, AUDIT_ACTIONS.CREATE, "contributors", { recordTitle: fullName, details: `Added community member ${u}` });
      setName(""); setUsername("");
      showToast("Member added.");
      await verify([u]);
    } catch (e) {
      alert(`Could not add the member: ${e.message}`);
    } finally {
      setBusy(false);
    }
  };

  const addMany = async (list, label, source) => {
    if (list.length === 0) return;
    setBusy(true);
    try {
      await addMembers(list);
      await addAudit(profile, AUDIT_ACTIONS.IMPORT, "contributors", { details: `${label}: added ${list.length} community member${list.length === 1 ? "" : "s"} (${source})` });
      await verify(list.map(m => m.wikimediaUsername));
      return true;
    } catch (e) {
      alert(`Could not add members: ${e.message}`);
      return false;
    } finally {
      setBusy(false);
    }
  };

  const addBulk = async () => {
    const seen = new Set(existing);
    const list = [];
    let skipped = 0;
    for (const line of bulk.split(/\r?\n/)) {
      if (!line.trim()) continue;
      const parts = line.split("|");
      const rawUser = parts.length > 1 ? parts.slice(1).join("|") : parts[0];
      const u = normalizeUsername(rawUser);
      if (!u || seen.has(u)) { skipped++; continue; }
      seen.add(u);
      const fullName = parts.length > 1 ? parts[0].trim() : "";
      list.push({ name: fullName || u, wikimediaUsername: u, isActive: true, source: "bulk" });
    }
    if (list.length === 0) { alert(skipped ? "All of these are already in the list." : "Paste at least one username."); return; }
    if (!(await addMany(list, "Bulk add", "bulk"))) return;
    setBulk("");
    showToast(`Added ${list.length} member${list.length === 1 ? "" : "s"}${skipped ? `, skipped ${skipped} duplicate${skipped === 1 ? "" : "s"}` : ""}.`);
  };

  const importVolunteers = async () => {
    const n = importable.length;
    if (!(await addMany(importable, "Import from Volunteers", "volunteers"))) return;
    showToast(`Imported ${n} from Volunteers.`);
  };

  const importParticipants = async () => {
    const n = importableParticipants.length;
    if (!window.confirm(`Add ${n} past event participant${n === 1 ? "" : "s"} to the community list? They will be included in monthly reports.`)) return;
    if (!(await addMany(importableParticipants, "Import from Participants", "participants"))) return;
    showToast(`Imported ${n} from Participants.`);
  };

  // Same person entered twice with different capitals ("amina juma" / "Amina Juma").
  const duplicates = useMemo(() => {
    const groups = new Map();
    members.forEach(m => {
      const k = userKey(m.wikimediaUsername);
      if (!k) return;
      if (!groups.has(k)) groups.set(k, []);
      groups.get(k).push(m);
    });
    return [...groups.values()].filter(g => g.length > 1);
  }, [members]);

  // Which usernames don't exist on Swahili Wikipedia (typos → their reports show 0).
  const checkAllUsernames = async () => {
    setUserCheck({ busy: true, notFound: new Set() });
    try {
      const res = await checkUsernames(members.map(m => m.wikimediaUsername).filter(Boolean), WIKIS[0].id);
      setUserCheck({ busy: false, notFound: new Set(res.missing) });
    } catch (e) {
      setUserCheck(null);
      alert(`Could not check usernames: ${e.message}`);
    }
  };

  const saveUsername = async (m) => {
    const u = normalizeUsername(fixUser[m.id]);
    if (!u) return;
    const same = members.find(x => x.id !== m.id && userKey(x.wikimediaUsername) === u.toLowerCase());
    if (same) { alert(`${u} is already a member (${same.name}). Remove one of them instead.`); return; }
    await updateCommunityMember(m.id, { wikimediaUsername: u });
    await addAudit(profile, AUDIT_ACTIONS.UPDATE, "contributors", { targetId: m.id, recordTitle: m.name, details: `Changed username ${m.wikimediaUsername} → ${u}` });
    setFixUser(f => ({ ...f, [m.id]: undefined }));
    setUserCheck(c => c && { ...c, notFound: new Set([...c.notFound].filter(x => x !== normalizeUsername(m.wikimediaUsername))) });
    showToast("Username saved. Fetch the reports again to count their edits.");
  };

  // Keep one member of a duplicate group, remove the others (admins).
  const keepOnly = async (group, keep) => {
    const others = group.filter(m => m.id !== keep.id);
    if (!window.confirm(`Keep ${keep.name} (${keep.wikimediaUsername}) and remove ${others.map(m => `${m.name} (${m.wikimediaUsername})`).join(", ")}? Saved reports keep their old rows.`)) return;
    for (const m of others) {
      await deleteCommunityMember(m.id);
      await addAudit(profile, AUDIT_ACTIONS.DELETE, "contributors", { targetId: m.id, recordTitle: m.name, details: `Removed duplicate member ${m.wikimediaUsername} (kept ${keep.wikimediaUsername})` });
    }
    showToast("Duplicate removed.");
  };

  // Fix a member's name (used on reports and certificates).
  const saveName = async (m, raw) => {
    const value = String(raw || "").replace(/\s+/g, " ").trim();
    if (!value) { alert("The name can't be empty."); return; }
    if (value === (m.name || "")) { setEditing(null); return; }
    try {
      await updateCommunityMember(m.id, { name: value });
      await addAudit(profile, AUDIT_ACTIONS.UPDATE, "contributors", {
        targetId: m.id, recordTitle: value, details: `Renamed community member ${m.wikimediaUsername}: "${m.name || ""}" → "${value}"`,
      });
      setEditing(null);
      showToast("Name saved.");
    } catch (e) {
      alert(`Could not save the name: ${e.message}`);
    }
  };

  const toggleActive = async (m) => {
    await updateCommunityMember(m.id, { isActive: m.isActive === false });
  };

  const del = async (m) => {
    if (!window.confirm(`Remove ${m.name} (${m.wikimediaUsername}) from the community list?`)) return;
    await deleteCommunityMember(m.id);
    await addAudit(profile, AUDIT_ACTIONS.DELETE, "contributors", { targetId: m.id, recordTitle: m.name, details: `Removed community member ${m.wikimediaUsername}` });
    showToast("Member removed.");
  };

  const q = search.toLowerCase();
  const toCheck = members.filter(m => nameProblem(m.name, m.wikimediaUsername)).length;
  const filtered = members.filter(m =>
    (!q || m.name?.toLowerCase().includes(q) || m.wikimediaUsername?.toLowerCase().includes(q))
    && (!onlyCheck || nameProblem(m.name, m.wikimediaUsername))
  );

  // Which Wikimedia projects each member edits (global account on Meta).
  const checkProjects = async () => {
    const names = filtered.map(m => m.wikimediaUsername).filter(u => normalizeUsername(u));
    if (!names.length) return;
    setProjBusy({ done: 0, total: names.length });
    try {
      const res = await fetchUserProjects(names, { onProgress: (done, total) => setProjBusy({ done, total }) });
      setProjects(prev => new Map([...(prev || []), ...res]));
    } catch (e) {
      alert(`Could not check projects: ${e.message}`);
    } finally {
      setProjBusy(null);
    }
  };

  return (
    <div>
      <div className="alert alert-info">
        This is the whole community, the same in every grant. A member shows up in a grant's reports, year summary and certificates only when they took part
        in that grant — on its participant list, a registration form or one of its events. Taking part in this grant and an earlier one makes them <strong>Returning</strong> (retention).
      </div>
      {canEdit && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: 16, marginBottom: 20 }}>
          <div className="panel" style={{ margin: 0 }}>
            <div className="panel-title">Add one member</div>
            <div className="field"><label>Full name</label>
              <input value={name} onChange={e => setName(e.target.value)} placeholder="e.g. Amina Juma" />
            </div>
            <div className="field"><label>Wikipedia username <span className="req">★</span></label>
              <input value={username} onChange={e => setUsername(e.target.value)} placeholder="e.g. Amina Juma"
                autoComplete="off" autoCorrect="off" autoCapitalize="none" spellCheck={false} />
            </div>
            <div className="btn-row"><button className="btn btn-primary" onClick={addOne} disabled={busy}>+ Add member</button></div>
          </div>

          <div className="panel" style={{ margin: 0 }}>
            <div className="panel-title">Bulk add</div>
            <div className="field"><label>One per line: <code>username</code> or <code>Full name | username</code></label>
              <textarea rows={5} value={bulk} onChange={e => setBulk(e.target.value)} spellCheck={false}
                placeholder={"Amina Juma | Amina_Juma\nBaraka2024"} />
            </div>
            <div className="btn-row">
              <button className="btn btn-primary" onClick={addBulk} disabled={busy || !bulk.trim()}>Add all</button>
              <button className="btn" onClick={importVolunteers} disabled={busy || importable.length === 0}
                title={importable.length === 0 ? "Every volunteer with a Wikipedia username is already in the list" : ""}>
                Import {importable.length} from Volunteers
              </button>
              <button className="btn" onClick={importParticipants} disabled={busy || importableParticipants.length === 0}
                title={importableParticipants.length === 0 ? "Every event participant with a Wikipedia username is already in the list" : ""}>
                Import {importableParticipants.length} from Participants
              </button>
            </div>
            {participantsNoUsername > 0 && (
              <div style={{ fontSize: 12, color: "#888", marginTop: 8 }}>
                {participantsNoUsername} participant{participantsNoUsername === 1 ? " has" : "s have"} no Wikipedia username and can't be checked. Add their username on the Participants page first.
              </div>
            )}
          </div>
        </div>
      )}

      {canEdit && members.length > 0 && (
        <div className="panel" style={{ marginBottom: 16 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
            <div>
              <div className="panel-title" style={{ margin: 0 }}>Check usernames</div>
              <div style={{ fontSize: 12, color: "#888" }}>
                A wrong username means 0 articles in every report. Capital letters matter on Wikipedia after the first letter.
              </div>
            </div>
            <button className="btn btn-sm btn-primary" onClick={checkAllUsernames} disabled={userCheck?.busy}>
              {userCheck?.busy ? "Checking…" : "🔎 Check all on Swahili Wikipedia"}
            </button>
          </div>

          {duplicates.length > 0 && (
            <div style={{ marginTop: 12 }}>
              <div style={{ fontSize: 13, fontWeight: 600, color: "#c0392b", marginBottom: 6 }}>Same person entered more than once ({duplicates.length})</div>
              {duplicates.map(g => (
                <div key={g[0].id} style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center", fontSize: 13, padding: "6px 0", borderBottom: "1px solid #f0efe9" }}>
                  {g.map(m => (
                    <span key={m.id} style={{ display: "inline-flex", gap: 6, alignItems: "center", border: "1px solid #e4e2da", borderRadius: 6, padding: "3px 8px" }}>
                      {m.name} · <code>{m.wikimediaUsername}</code>
                      {userCheck && !userCheck.busy && (userCheck.notFound.has(normalizeUsername(m.wikimediaUsername))
                        ? <span className="badge badge-red" style={{ fontSize: 10 }}>not on Wikipedia</span>
                        : <span className="badge badge-green" style={{ fontSize: 10 }}>exists</span>)}
                      {isAdmin && <button className="btn btn-sm" style={{ padding: "0 6px", fontSize: 11 }} onClick={() => keepOnly(g, m)}>Keep this one</button>}
                    </span>
                  ))}
                  {!isAdmin && <span style={{ fontSize: 11, color: "#888" }}>An admin can remove the extra copy.</span>}
                </div>
              ))}
            </div>
          )}

          {userCheck && !userCheck.busy && (
            userCheck.notFound.size === 0
              ? <div className="alert alert-success" style={{ marginTop: 12, marginBottom: 0 }}>Every username exists on Swahili Wikipedia.</div>
              : (
                <div style={{ marginTop: 12 }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: "#d97706", marginBottom: 6 }}>Not found on Swahili Wikipedia ({userCheck.notFound.size})</div>
                  <div style={{ fontSize: 12, color: "#888", marginBottom: 6 }}>Usually a typo or wrong capitals. Type the exact username from their Wikipedia page and save.</div>
                  {members.filter(m => userCheck.notFound.has(normalizeUsername(m.wikimediaUsername))).map(m => (
                    <div key={m.id} style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap", fontSize: 13, padding: "4px 0" }}>
                      <span style={{ minWidth: 160 }}>{m.name}</span>
                      <code style={{ color: "#c0392b" }}>{m.wikimediaUsername}</code>
                      <span>→</span>
                      <input value={fixUser[m.id] ?? ""} onChange={e => setFixUser(f => ({ ...f, [m.id]: e.target.value }))} placeholder="Correct username"
                        style={{ fontSize: 13, width: 200 }} autoComplete="off" autoCapitalize="none" spellCheck={false} />
                      <button className="btn btn-sm" disabled={!normalizeUsername(fixUser[m.id])} onClick={() => saveUsername(m)}>Save</button>
                    </div>
                  ))}
                </div>
              )
          )}
        </div>
      )}

      {missing.length > 0 && (
        <div className="alert alert-warn" style={{ display: "flex", justifyContent: "space-between", gap: 12 }}>
          <span>These usernames were not found on Swahili Wikipedia. Check the spelling: <strong>{missing.join(", ")}</strong></span>
          <button className="btn btn-sm" onClick={() => setMissing([])}>Dismiss</button>
        </div>
      )}

      <div style={{ display: "flex", gap: 10, justifyContent: "space-between", alignItems: "center", marginBottom: 12, flexWrap: "wrap" }}>
        <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search name or username..." style={{ flex: 1, minWidth: 200, fontSize: 13 }} />
        <span style={{ fontSize: 12, color: "#888" }}>{members.length} member{members.length === 1 ? "" : "s"}, {members.filter(m => m.isActive !== false).length} in reports
          {grantPeople && <>, <strong>{members.filter(m => grantPeople.has(normalizeUsername(m.wikimediaUsername))).length} took part in {grantTitle || "this grant"}</strong></>}
          {returning.size > 0 && <>, <strong style={{ color: "#2563eb" }}>{members.filter(m => returning.has(normalizeUsername(m.wikimediaUsername))).length} returning from earlier grants</strong> (retention)</>}</span>
        {toCheck > 0 && (
          <button className={`btn btn-sm ${onlyCheck ? "btn-primary" : ""}`} onClick={() => setOnlyCheck(v => !v)}
            title="Names that may not look right on a certificate (username, one name, all capitals…)">
            {onlyCheck ? "Show all" : `✎ ${toCheck} name${toCheck === 1 ? "" : "s"} to check`}
          </button>
        )}
        <button className="btn btn-sm" onClick={checkProjects} disabled={!!projBusy || filtered.length === 0}
          title="Look up each member's global account to see every Wikimedia project they edit (all-time edit counts)">
          {projBusy ? `Checking ${projBusy.done} of ${projBusy.total}…` : `🌍 Check projects${q ? ` (${filtered.length} shown)` : ""}`}
        </button>
      </div>

      <div className="panel" style={{ padding: 0 }}>
        {filtered.length === 0 ? (
          <div className="empty">{members.length === 0 ? "No community members yet. Add them above, or import from Volunteers or Participants." : "No members match your search."}</div>
        ) : (
          <div style={{ overflowX: "auto" }}>
            <table>
              <thead><tr><th>Name</th><th>Username</th><th>Took part in</th>{projects && <th>Projects (all-time edits)</th>}<th>Source</th><th>In reports</th>{isAdmin && <th>Actions</th>}</tr></thead>
              <tbody>
                {filtered.map(m => (
                  <tr key={m.id}>
                    <td style={{ fontWeight: 500, minWidth: 180 }}>
                      {editing?.id === m.id ? (() => {
                        const suggestion = participantName.get(normalizeUsername(m.wikimediaUsername));
                        const tidy = tidyName(editing.value);
                        return (
                          <div>
                            <input autoFocus value={editing.value} onChange={e => setEditing({ id: m.id, value: e.target.value })}
                              onKeyDown={e => { if (e.key === "Enter") saveName(m, editing.value); if (e.key === "Escape") setEditing(null); }}
                              style={{ fontSize: 13, width: "100%", minWidth: 160 }} placeholder="Full name as on the certificate" />
                            <div style={{ display: "flex", gap: 4, marginTop: 4, flexWrap: "wrap" }}>
                              <button className="btn btn-sm btn-primary" onClick={() => saveName(m, editing.value)}>Save</button>
                              <button className="btn btn-sm" onClick={() => setEditing(null)}>Cancel</button>
                              {tidy && tidy !== editing.value && <button className="btn btn-sm" onClick={() => setEditing({ id: m.id, value: tidy })} title="Fix spaces and capital letters">Tidy → {tidy}</button>}
                              {suggestion && suggestion !== editing.value && <button className="btn btn-sm" onClick={() => setEditing({ id: m.id, value: suggestion })} title="Name from the Participants list">Use “{suggestion}”</button>}
                            </div>
                          </div>
                        );
                      })() : (
                        <>
                          {m.name}
                          {canEdit && <button className="btn btn-sm" style={{ marginLeft: 6, padding: "0 6px", fontSize: 11 }} title="Edit name (used on reports and certificates)" onClick={() => setEditing({ id: m.id, value: m.name || "" })}>✎</button>}
                          {(() => { const why = nameProblem(m.name, m.wikimediaUsername); return why && <span className="badge badge-amber" style={{ marginLeft: 6, fontSize: 10 }} title="Check this name before printing certificates">{why}</span>; })()}
                          {returning.has(normalizeUsername(m.wikimediaUsername)) && <span className="badge badge-blue" style={{ marginLeft: 6, fontSize: 10 }} title="Also a member in an earlier grant — counts as retention">Returning</span>}
                        </>
                      )}
                    </td>
                    <td style={{ fontSize: 12 }}>
                      <a href={contribsLink(WIKIS[0].id, m.wikimediaUsername || "")} target="_blank" rel="noopener noreferrer" style={{ color: "#2563eb" }}>{m.wikimediaUsername}</a>
                    </td>
                    <td style={{ fontSize: 12 }}>
                      {grantsOf(m).length ? grantsOf(m).join(", ") : <span style={{ color: "#aaa" }}>no grant activity recorded</span>}
                      {grantPeople && grantPeople.has(normalizeUsername(m.wikimediaUsername)) && <span className="badge badge-green" style={{ marginLeft: 6, fontSize: 10 }}>this grant</span>}
                    </td>
                    {projects && (
                      <td style={{ fontSize: 12, maxWidth: 320 }}>
                        {(() => {
                          const list = projects.get(normalizeUsername(m.wikimediaUsername));
                          if (!list) return <span style={{ color: "#aaa" }}>not checked</span>;
                          if (!list.length) return <span style={{ color: "#c0392b" }}>no edits / no global account</span>;
                          return list.slice(0, 6).map(p => (
                            <span key={p.host} className={`badge ${WIKIS.some(w => w.id === p.host) ? "badge-green" : "badge-gray"}`} style={{ marginRight: 4, marginBottom: 2, fontSize: 10, display: "inline-block" }}>
                              {p.label} {p.edits.toLocaleString()}
                            </span>
                          )).concat(list.length > 6 ? [<span key="more" style={{ color: "#888" }}>+{list.length - 6} more</span>] : []);
                        })()}
                      </td>
                    )}
                    <td style={{ fontSize: 12, color: "#666" }}>{m.source || "manual"}</td>
                    <td><input type="checkbox" checked={m.isActive !== false} disabled={!canEdit} onChange={() => toggleActive(m)} /></td>
                    {isAdmin && <td><button className="btn btn-sm btn-danger" onClick={() => del(m)}>✕</button></td>}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

// ── Page ───────────────────────────────────────────────────────────────────────
export default function ActiveContributors({ profile, currentGrant, grantId = "", firstGrantId = "", grants = [] }) {
  const [tab,        setTab]        = useState("Report");
  const [allMembers, setMembers]    = useState([]);
  const [allReports, setReports]    = useState([]);
  const [programs,   setPrograms]   = useState([]);
  const [registrations, setRegistrations] = useState([]);
  const [allVolunteers, setVolunteers] = useState([]);
  const [participants, setParticipants] = useState([]);
  const [settings,   setSettings]   = useState(null);
  const [allEvents,  setEvents]     = useState([]);
  const [forms,      setForms]      = useState([]);
  const [scope,      setScope]      = useState(DEFAULT_SCOPE);
  const [toast,      setToast]      = useState("");
  const canEdit = ["admin", "coordinator"].includes(profile?.role);
  // Matches the Firestore rules: only admins may delete (same as volunteers).
  const isAdmin = profile?.role === "admin";

  useEffect(() => {
    const u1 = listenCommunityMembers(setMembers);
    const u2 = listenContributorReports(setReports);
    const u3 = listenVolunteers(setVolunteers);
    const u4 = listenParticipants(setParticipants);
    const u5 = listenSettings(setSettings);
    const u6 = listenContributorEvents(setEvents);
    const u7 = listenForms(setForms);
    const u8 = listenPrograms(setPrograms);
    getAllRegistrations().then(setRegistrations).catch(() => {});
    return () => { u1(); u2(); u3(); u4(); u5(); u6(); u7(); u8(); };
  }, []);

  const showToast = (msg) => { setToast(msg); setTimeout(() => setToast(""), 3000); };
  // Name and logo for printed reports and certificates (same as Participants certificates)
  const org = { orgName: settings?.org?.name || "Wikimedians of Kilimanjaro", logoUrl: window.location.origin + logo };
  const signature = settings?.certificate || {};
  // Real names for usernames that come from events (participants list has them).
  const nameByUsername = useMemo(() => {
    const m = new Map();
    for (const p of participants) {
      const u = normalizeUsername(p.wikimediaUsername);
      if (u && (p.name || "").trim() && !m.has(u)) m.set(u, p.name.trim());
    }
    return m;
  }, [participants]);
  const nameFor = (u) => nameByUsername.get(u) || u;
  // ── This grant only ──
  // Community members are one list for all grants. A grant's members are the
  // community members who TOOK PART in that grant (participant list,
  // registration forms, events inside its dates). Returning = took part in this
  // grant and an earlier one (retention). Reports count only the grant's months.
  const monthRange = grantMonthRange(currentGrant);
  const noDates    = !!currentGrant && !monthRange;
  const participation = useMemo(
    () => grantParticipation({ grants, participants, programs, forms, registrations, events: allEvents, firstGrantId, members: allMembers }),
    [grants, participants, programs, forms, registrations, allEvents, firstGrantId, allMembers],
  );
  const grantPeople = currentGrant ? (participation.get(grantId) || new Set()) : null;
  const members    = useMemo(
    () => (grantPeople ? allMembers.filter(m => grantPeople.has(normalizeUsername(m.wikimediaUsername))) : allMembers),
    [allMembers, grantPeople],
  );
  const returning  = useMemo(() => (grantId ? returningPeople(participation, grants, grantId) : new Set()), [participation, grants, grantId]);
  const earlierSet = useMemo(() => (grantId ? earlierPeople(participation, grants, grantId) : new Set()), [participation, grants, grantId]);
  const grantOrder = useMemo(() => sortGrants(grants), [grants]);
  const grantsOf   = (m) => {
    const u = normalizeUsername(m.wikimediaUsername);
    return grantOrder.filter(g => participation.get(g.id)?.has(u)).map(g => g.title || g.grantNumber || "Untitled grant");
  };
  const inGrant    = (m) => !currentGrant || (!!monthRange && m >= monthRange.start && m <= monthRange.end);
  // Saved reports list everyone checked that month — show only this grant's members.
  const memberSet  = useMemo(() => new Set(members.map(m => normalizeUsername(m.wikimediaUsername)).filter(Boolean)), [members]);
  const reports    = allReports.filter(r => inGrant(r.month)).map(r => (currentGrant ? reportForMembers(r, memberSet, isEditing) : r));
  const events     = allEvents.filter(ev => !currentGrant || (!!monthRange && (ev.start || "").slice(0, 7) <= monthRange.end && (ev.end || "").slice(0, 7) >= monthRange.start));
  const volunteers = allVolunteers.filter(v => belongsToGrant(v, grantId, { firstGrantId, programs }));
  const grantParticipants = participantsForGrant(participants, programs, grantId, { forms, firstGrantId });
  const addMembers = (list) => addCommunityMembersBulk(list, { existing: allMembers });

  // Report, History and Year summary only see reports counted the chosen way.
  const scopedReports = useMemo(() => reports.filter(r => reportScope(r) === scope), [reports, scope]);

  return (
    <div>
      {toast && <div style={{ position: "fixed", bottom: 24, right: 24, background: "#2d7a4f", color: "#fff", padding: "10px 18px", borderRadius: 8, fontSize: 13, fontWeight: 500, zIndex: 9999 }}>✓ {toast}</div>}
      <div className="page-title">Active contributors</div>
      <div className="page-sub">Community members who edited at least the set number of different Wikipedia articles in a month.</div>
      {noDates && (
        <div className="alert alert-warn">This grant has no start and end dates yet, so there are no months to report on. Add them on the Grant page (edit this grant). Members can still be added.</div>
      )}
      {monthRange && monthRange.start > currentMonth() && (
        <div className="alert alert-info">This grant starts in {monthLabel(monthRange.start)}. Reports can be fetched from then.</div>
      )}

      {SCOPED_TABS.includes(tab) && (
        <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", margin: "4px 0 16px", fontSize: 13 }}>
          <span style={{ color: "#666" }}>Count contributions from:</span>
          {SCOPES.map(sc => (
            <button key={sc.id} className={`btn btn-sm ${scope === sc.id ? "btn-primary" : ""}`} onClick={() => setScope(sc.id)} title={sc.long}>{sc.label}</button>
          ))}
          <span style={{ fontSize: 12, color: "#888" }}>
            {scope === "events"
              ? "Only edits made in Kilimanjaro events (Events tab) — what our programs produced."
              : "Every edit on the wiki, including other groups' events — recognises work across the whole wiki."}
          </span>
        </div>
      )}

      <div className="tab-bar" style={{ marginBottom: 20 }}>
        {TABS.map(t => (
          <button key={t} className={`tab-btn ${tab === t ? "active" : ""}`} onClick={() => setTab(t)}>
            {t}
            {t === "Community members" && allMembers.length > 0 && <span style={{ marginLeft: 6, fontSize: 11, color: "#888" }}>{allMembers.length}</span>}
            {t === "Events" && events.length > 0 && <span style={{ marginLeft: 6, fontSize: 11, color: "#888" }}>{events.length}</span>}
          </button>
        ))}
      </div>

      {tab === "Report"  && !noDates && !(monthRange && monthRange.start > currentMonth()) && <Report  members={members} community={allMembers} reports={scopedReports} allReports={allReports} earlier={earlierSet} events={events} scope={scope} nameFor={nameFor} addMembers={addMembers} monthRange={monthRange} profile={profile} canEdit={canEdit} showToast={showToast} org={org} />}
      {tab === "History" && <History reports={scopedReports} />}
      {tab === "Year summary" && <YearSummary members={members} reports={scopedReports} scope={scope} currentGrant={currentGrant} profile={profile} org={org} signature={signature} returning={returning} />}
      {tab === "Events"  && <Events events={events} members={allMembers} forms={forms} nameFor={nameFor} addMembers={addMembers} earlier={earlierSet} profile={profile} canEdit={canEdit} isAdmin={isAdmin} showToast={showToast} />}
      {tab === "Community members" && <Members members={allMembers} volunteers={volunteers} participants={grantParticipants} participantName={nameByUsername} profile={profile} canEdit={canEdit} isAdmin={isAdmin} showToast={showToast}
        addMembers={addMembers} returning={returning} grantPeople={grantPeople} grantsOf={grantsOf} grantTitle={currentGrant?.title || currentGrant?.grantNumber || ""} />}
    </div>
  );
}
